        _updateBriefing(state) {
            var period = Math.min((state.currentPeriod || 1), 4);

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl) {
                if (window.mySimulation && window.mySimulation.t) {
                    nameEl.textContent = window.mySimulation.t(this.ROUND_NAME_KEYS[period - 1]);
                }
            }

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                if (window.mySimulation && window.mySimulation.t) {
                    briefEl.innerHTML = window.mySimulation.t(this.BRIEFING_KEYS[period - 1]);
                }
            }

            for (var i = 1; i <= 4; i++) {
                var group = document.getElementById('round' + i + 'Inputs');
                if (group) {
                    group.style.display = (i === period) ? 'block' : 'none';
                }
            }

            var fbCard = document.getElementById('feedbackCard');
            if (fbCard) fbCard.style.display = 'none';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new MesaAdapter(), {
            simulationType: 'mesa_negotiation',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

